import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]
BASE = ROOT / "problems" / "arrays"
common = ["Scan once to identify the boundary or state where the answer changes.", "Test already ordered, reversed, duplicate, and minimum-size inputs."]
tasks = [
 ("41-shortest-unsorted-continuous-subarray","Shortest Unsorted Continuous Subarray","Medium","Traversal","findUnsortedSubarray","int","Given an integer array `nums`, find the shortest contiguous segment which, when sorted in non-decreasing order, makes the entire array non-decreasing. Return the segment length, or 0 if the array is already sorted. Input: `nums`. Output: the minimum length.",["1 <= nums.length <= 100000","-100000 <= nums[i] <= 100000"],"O(n)","O(1)","        n = len(nums)\n        left = -1\n        right = -2\n        high = nums[0]\n        low = nums[-1]\n        for i in range(1, n):\n            high = max(high, nums[i])\n            if nums[i] < high:\n                right = i\n        for i in range(n - 2, -1, -1):\n            low = min(low, nums[i])\n            if nums[i] > low:\n                left = i\n        return right - left + 1","        int n = nums.length, left = -1, right = -2, high = nums[0], low = nums[n - 1];\n        for (int i = 1; i < n; i++) { high = Math.max(high, nums[i]); if (nums[i] < high) right = i; }\n        for (int i = n - 2; i >= 0; i--) { low = Math.min(low, nums[i]); if (nums[i] > low) left = i; }\n        return right - left + 1;",[[2,6,4,8,10,9,15],5],[[1,2,3,4],[1],[2,1],[1,3,2,2,2],[5,4,3,2,1],[-1,0,2,1,3],[1,2,4,3,5,6],[1,5,3,4,2,6],[1,2,3,3,3],[3,1,2,0]]),
 ("42-find-all-disappeared-numbers","Find All Disappeared Numbers","Easy","In-Place Operations","findDisappearedNumbers","int[]","An array `nums` has length `n`, and each value is in the range 1 through `n`. Return, in increasing order, every value in that range that does not occur in `nums`. Input: `nums`. Output: the list of missing values.",["1 <= nums.length <= 100000","1 <= nums[i] <= nums.length"],"O(n)","O(n)","        present = set(nums)\n        return [x for x in range(1, len(nums) + 1) if x not in present]","        boolean[] present = new boolean[nums.length + 1];\n        for (int x : nums) present[x] = true;\n        int count = 0; for (int x = 1; x <= nums.length; x++) if (!present[x]) count++;\n        int[] answer = new int[count]; int at = 0;\n        for (int x = 1; x <= nums.length; x++) if (!present[x]) answer[at++] = x;\n        return answer;",[[4,3,2,7,8,2,3,1],[4,4,4,4]],[[1],[1,1],[2,2],[1,2,3],[3,3,3],[1,4,4,3],[2,1,2,1],[6,5,4,3,2,1],[2,2,1,1],[5,1,5,2,2]]),
 ("43-find-all-duplicate-values","Find All Duplicate Values","Medium","Traversal","findDuplicates","int[]","An array `nums` has length `n`, and each value is between 1 and `n`. Values occur once or twice. Return all values that occur twice, in increasing order. Input: `nums`. Output: the sorted duplicate values.",["1 <= nums.length <= 100000","1 <= nums[i] <= nums.length","Each value appears at most twice"],"O(n)","O(n)","        counts = [0] * (len(nums) + 1)\n        for x in nums:\n            counts[x] += 1\n        return [x for x in range(1, len(counts)) if counts[x] == 2]","        int[] counts = new int[nums.length + 1];\n        for (int x : nums) counts[x]++;\n        int size = 0; for (int x = 1; x < counts.length; x++) if (counts[x] == 2) size++;\n        int[] answer = new int[size]; int at = 0;\n        for (int x = 1; x < counts.length; x++) if (counts[x] == 2) answer[at++] = x;\n        return answer;",[[4,3,2,7,8,2,3,1],[1,1,2]],[[1],[1,2],[2,2],[1,2,3],[3,3,2,1],[1,4,4,3],[2,1,2,1],[5,5,4,3,2,1],[2,2,1,1],[5,1,5,2,2]]),
 ("44-rearrange-into-arithmetic-progression","Rearrange Into an Arithmetic Progression","Easy","Traversal","canRearrangeArithmeticProgression","boolean","Given an integer array `nums`, determine whether its elements can be rearranged into an arithmetic progression. In such an ordering, the difference between each adjacent pair is constant. Input: `nums`. Output: true if a valid ordering exists, otherwise false.",["2 <= nums.length <= 100000","-1000000000 <= nums[i] <= 1000000000"],"O(n log n)","O(n)","        ordered = sorted(nums)\n        step = ordered[1] - ordered[0]\n        return all(ordered[i] - ordered[i - 1] == step for i in range(2, len(ordered)))","        int[] a = nums.clone(); Arrays.sort(a);\n        long step = (long) a[1] - a[0];\n        for (int i = 2; i < a.length; i++) if ((long) a[i] - a[i - 1] != step) return false;\n        return true;",[[3,5,1],[1,2,4]],[[1,1],[1,3],[3,3,3],[9,7,5,3],[0,-2,-4,-6],[1,2,3,5],[8,1,4,7,10],[1000000000,-1000000000,0],[-3,-1,0,2],[4,4,4,5]]),
 ("45-sum-of-absolute-differences-sorted-array","Sum of Absolute Differences in a Sorted Array","Medium","Prefix/Suffix","getAbsoluteDifferences","long[]","Given a non-decreasing integer array `nums`, return an array `answer` where `answer[i]` is the sum of `abs(nums[i] - nums[j])` over every index `j`. Input: sorted `nums`. Output: the corresponding sum array.",["2 <= nums.length <= 100000","-100000 <= nums[i] <= 100000","nums is sorted in non-decreasing order"],"O(n)","O(n)","        total = sum(nums)\n        left = 0\n        answer = []\n        n = len(nums)\n        for i, x in enumerate(nums):\n            answer.append(x * i - left + total - left - x * (n - i))\n            left += x\n        return answer","        int n = nums.length; long total = 0, left = 0;\n        for (int x : nums) total += x;\n        long[] answer = new long[n];\n        for (int i = 0; i < n; i++) { long x = nums[i]; answer[i] = x * i - left + total - left - x * (n - i); left += x; }\n        return answer;",[[2,3,5],[1,4,6,8,10]],[[0,0],[1,1,1],[1,2],[2,2,3],[0,5,10],[1,3,3,7],[1,2,3,4,5],[-5,-2,0,0,8],[100000,100000],[0,1,100000]]),
 ("46-increasing-triplet-subsequence","Increasing Triplet Subsequence","Medium","Traversal","increasingTriplet","boolean","Given an integer array `nums`, determine whether there are indices `i < j < k` such that `nums[i] < nums[j] < nums[k]`. The selected indices need not be adjacent. Input: `nums`. Output: true if such a triplet exists, otherwise false.",["1 <= nums.length <= 100000","-1000000000 <= nums[i] <= 1000000000"],"O(n)","O(1)","        first = second = float('inf')\n        for x in nums:\n            if x <= first:\n                first = x\n            elif x <= second:\n                second = x\n            else:\n                return True\n        return False","        long first = Long.MAX_VALUE, second = Long.MAX_VALUE;\n        for (int x : nums) { if (x <= first) first = x; else if (x <= second) second = x; else return true; }\n        return false;",[[1,2,3,4,5],[5,4,3,2,1]],[ [1,1,1],[2,1,5,0,4,6],[20,100,10,12,5,13],[1,2],[-1000000000,0,1000000000],[3,5,0,3,4],[1,5,0,4,1,6],[2,2,3,1,4],[10,9,8,7,6,1],[0,4,2,3] ]),
 ("47-longest-alternating-parity-run","Longest Alternating Parity Run","Easy","Traversal","longestAlternatingParityRun","int","Given a non-empty integer array `nums`, return the length of its longest contiguous segment in which every neighboring pair has opposite parity. Negative odd numbers count as odd. Input: `nums`. Output: the longest segment length.",["1 <= nums.length <= 100000","-1000000000 <= nums[i] <= 1000000000"],"O(n)","O(1)","        best = run = 1\n        for i in range(1, len(nums)):\n            run = run + 1 if (nums[i] - nums[i - 1]) % 2 != 0 else 1\n            best = max(best, run)\n        return best","        int best = 1, run = 1;\n        for (int i = 1; i < nums.length; i++) { run = ((nums[i] & 1) != (nums[i - 1] & 1)) ? run + 1 : 1; best = Math.max(best, run); }\n        return best;",[[1,2,3,4,5],[1,3,5,7]],[[0],[2,4,6],[1,2,4,5,8,9],[1,-2,3,-4],[0,1,0,1,0],[8,7,6,5,4],[1,1,2,2,3],[1000000000,-1,0,-3],[3,2,2,1,4,5],[0,-1,-2,3,4]]),
 ("48-array-nesting-length","Array Nesting Length","Medium","Traversal","arrayNesting","int","The array `nums` is a permutation of the integers from 0 through `n - 1`. Starting at index `i`, repeatedly visit the index named by the current value: `i, nums[i], nums[nums[i]], ...`. Return the largest number of distinct indices visited before a cycle repeats. Input: the permutation `nums`. Output: the maximum cycle length.",["1 <= nums.length <= 100000","nums is a permutation of [0, nums.length - 1]"],"O(n)","O(n)","        seen = [False] * len(nums)\n        best = 0\n        for start in range(len(nums)):\n            length = 0\n            i = start\n            while not seen[i]:\n                seen[i] = True\n                length += 1\n                i = nums[i]\n            best = max(best, length)\n        return best","        boolean[] seen = new boolean[nums.length]; int best = 0;\n        for (int start = 0; start < nums.length; start++) { int length = 0, i = start; while (!seen[i]) { seen[i] = true; length++; i = nums[i]; } best = Math.max(best, length); }\n        return best;",[[5,4,0,3,1,6,2],[0,1,2,3]],[[0],[1,0],[0,1,2],[1,2,0],[3,0,1,2],[2,0,4,1,3],[4,3,2,1,0],[0,2,1,4,3],[2,1,0,4,3],[1,0,3,2]]),
 ("49-maximum-sorted-chunks-permutation","Maximum Sorted Chunks in a Permutation","Medium","In-Place Operations","maxChunksToSorted","int","The array `nums` is a permutation of all integers from 0 through `n - 1`. Split it into the largest number of contiguous chunks such that sorting each chunk individually and concatenating the chunks produces the fully sorted array. Return the number of chunks. Input: the permutation `nums`. Output: the maximum chunk count.",["1 <= nums.length <= 100000","nums is a permutation of [0, nums.length - 1]"],"O(n)","O(1)","        chunks = high = 0\n        for i, x in enumerate(nums):\n            high = max(high, x)\n            if high == i:\n                chunks += 1\n        return chunks","        int chunks = 0, high = 0;\n        for (int i = 0; i < nums.length; i++) { high = Math.max(high, nums[i]); if (high == i) chunks++; }\n        return chunks;",[[4,3,2,1,0],[1,0,2,3,4]],[[0],[1,0],[0,1,2],[2,0,1],[0,2,1,3],[1,2,0,3],[3,0,1,2],[0,1,3,2,4],[4,3,2,1,0],[2,1,0,3,4,5]]),
 ("50-maximum-subarray-sum-with-one-deletion","Maximum Subarray Sum with One Deletion","Medium","Subarrays","maximumSumWithOneDeletion","int","Given a non-empty integer array `nums`, choose a non-empty contiguous subarray and optionally delete at most one element from it. After deletion, at least one element must remain. Return the largest possible sum. Input: `nums`. Output: the maximum sum.",["1 <= nums.length <= 100000","-10000 <= nums[i] <= 10000"],"O(n)","O(1)","        keep = nums[0]\n        drop = 0\n        best = nums[0]\n        for x in nums[1:]:\n            drop = max(keep, drop + x)\n            keep = max(x, keep + x)\n            best = max(best, keep, drop)\n        return best","        int keep = nums[0], drop = 0, best = nums[0];\n        for (int i = 1; i < nums.length; i++) { int x = nums[i]; drop = Math.max(keep, drop + x); keep = Math.max(x, keep + x); best = Math.max(best, Math.max(keep, drop)); }\n        return best;",[[1,-2,0,3],[1,-2,-2,3]],[[5,-3,-3,5],[-1,-1,-1],[1],[0,0,0],[-10,4,-2,3,-20,5],[-3,2,-1,-2,4],[8,-1,6,-10,7],[2,-5,4,-1,3],[-2,3,-2,3,-2],[100,-100,100,-1,100]])
]

topics={t["id"]:t for t in json.loads((ROOT/"problems"/"topics.json").read_text())}
roster_path=ROOT/"problems"/"roster.json"
roster=json.loads(roster_path.read_text())
example_data={
 "41-shortest-unsorted-continuous-subarray":[([2,6,4,8,10,9,15],5),([1,2,3,4],0)],
 "42-find-all-disappeared-numbers":[([4,3,2,7,8,2,3,1],[5,6]),([4,4,4,4],[1,2,3])],
 "43-find-all-duplicate-values":[([4,3,2,7,8,2,3,1],[2,3]),([1,1,2],[1])],
 "44-rearrange-into-arithmetic-progression":[([3,5,1],True),([1,2,4],False)],
 "45-sum-of-absolute-differences-sorted-array":[([2,3,5],[4,3,5]),([1,4,6,8,10],[15,9,7,9,15])],
 "46-increasing-triplet-subsequence":[([1,2,3,4,5],True),([5,4,3,2,1],False)],
 "47-longest-alternating-parity-run":[([1,2,3,4,5],5),([1,3,5,7],1)],
 "48-array-nesting-length":[([5,4,0,3,1,6,2],4),([0,1,2,3],1)],
 "49-maximum-sorted-chunks-permutation":[([4,3,2,1,0],1),([1,0,2,3,4],4)],
 "50-maximum-subarray-sum-with-one-deletion":[([1,-2,0,3],4),([1,-2,-2,3],3)],
}
for slug,title,diff,subtopic,method,ret,desc,constraints,time,space,py,java,examples,tests in tasks:
    examples=example_data[slug]
    folder=BASE/slug; folder.mkdir(exist_ok=True)
    meta={"title":title,"difficulty":diff,"subtopic":subtopic,"companies":["Amazon","Google","Microsoft"],"description":desc,"constraints":constraints,"hints":common,"examples":[{"input":f"nums = {arr}","output":str(out).lower() if isinstance(out,bool) else str(out)} for arr,out in examples],"timeComplexity":time,"spaceComplexity":space,"compare":"exact","signature":{"kind":"function","method":method,"params":[{"name":"nums","type":"int[]"}],"returns":ret}}
    (folder/"problem.json").write_text(json.dumps(meta,indent=2)+"\n")
    ret_py={"int":"int","int[]":"List[int]","long[]":"List[int]","boolean":"bool"}[ret]
    (folder/"solution.py").write_text(f"class Solution:\n    def {method}(self, nums: List[int]) -> {ret_py}:\n"+py+"\n")
    ret_java={"int":"int","int[]":"int[]","long[]":"long[]","boolean":"boolean"}[ret]
    (folder/"Solution.java").write_text(f"class Solution {{\n    public {ret_java} {method}(int[] nums) {{\n"+java+"\n    }\n}\n")
    all_cases=[x for x,_ in examples]+tests
    if len(all_cases)<11: raise ValueError((slug,len(all_cases)))
    vis=all_cases[:3]; hid=all_cases[3:]
    (folder/"tests.py").write_text("def visible():\n    return "+repr([{"in":{"nums":a}} for a in vis])+"\n\ndef hidden():\n    return "+repr([{"in":{"nums":a}} for a in hid])+"\n")
    roster.setdefault("arrays",[]).append([slug,title,diff,subtopic,None])
roster_path.write_text(json.dumps(roster,indent=2)+"\n")
print(f"Created {len(tasks)} array questions")
